-- Worker-local retention for already-fetched generated bytes. The catalog sits
-- below logical decoding: it wraps one version-scoped backend `read` and
-- serves repeat reads of retained physical strings without a second native
-- file read. Only version-confined `assets/generated/` and `data/generated/`
-- bytes are eligible; private derivatives, staging roots, and publication
-- journals always read through. Bounded by a fixed byte ceiling with
-- least-recently-used retirement; a single blob larger than the ceiling
-- streams through without retention, and missing or failed reads are never
-- cached. Love-free and single-thread by construction: the owning worker is
-- the only caller.

---@class CompressedAssetCatalogEntry
---@field data string retained physical bytes
---@field size integer byte length counted toward the ceiling
---@field older string? next-older retained key
---@field newer string? next-newer retained key

---@class CompressedAssetCatalog
---@field private _read fun(fullPath: string): string?, number|string?
---@field private _prefix string version-prefixed physical root with its slash boundary
---@field private _limit integer fixed resident-byte ceiling
---@field private _entries table<string, CompressedAssetCatalogEntry> retained bytes by physical path
---@field private _oldest string? least-recently-used retained key
---@field private _newest string? most-recently-used retained key
---@field private _retainedBytes integer bytes held by current entries only
---@field private _reads integer native delegate invocations
---@field private _hits integer reads served from retained bytes
---@field private _evictions integer entries retired to reclaim budget
local CompressedAssetCatalog = {}
CompressedAssetCatalog.__index = CompressedAssetCatalog

---@param fullPath string
---@return boolean
function CompressedAssetCatalog:_eligible(fullPath)
  if type(fullPath) ~= "string" then
    return false
  end
  if fullPath:sub(1, #self._prefix) ~= self._prefix then
    return false
  end
  local rest = fullPath:sub(#self._prefix + 1)
  if
    rest:sub(1, #"assets/generated/") ~= "assets/generated/" and rest:sub(1, #"data/generated/") ~= "data/generated/"
  then
    return false
  end
  if fullPath:find("/_prepared/", 1, true) ~= nil then
    return false
  end
  if fullPath:find("__g4", 1, true) ~= nil then
    return false
  end
  return true
end

---@param key string retained entry to move to the newest position
function CompressedAssetCatalog:_touch(key)
  local entry = self._entries[key]
  assert(entry ~= nil, "catalog touch requires a retained entry")
  if self._newest == key then
    return
  end
  local older, newer = entry.older, entry.newer
  if older ~= nil then
    local olderEntry = assert(self._entries[older], "catalog order links must resolve")
    olderEntry.newer = newer
  else
    self._oldest = newer
  end
  if newer ~= nil then
    local newerEntry = assert(self._entries[newer], "catalog order links must resolve")
    newerEntry.older = older
  end
  entry.older = self._newest
  entry.newer = nil
  if self._newest ~= nil then
    local newestEntry = assert(self._entries[self._newest], "catalog order links must resolve")
    newestEntry.newer = key
  end
  self._newest = key
  if self._oldest == nil then
    self._oldest = key
  end
end

---Removes the least-recently-used retained entry.
function CompressedAssetCatalog:_evictOldest()
  local oldest = self._oldest
  assert(oldest ~= nil, "catalog eviction requires a retained entry")
  local entry = assert(self._entries[oldest], "catalog order links must resolve")
  self._entries[oldest] = nil
  self._oldest = entry.newer
  if entry.newer ~= nil then
    local newerEntry = assert(self._entries[entry.newer], "catalog order links must resolve")
    newerEntry.older = nil
  else
    self._newest = nil
  end
  self._retainedBytes = self._retainedBytes - entry.size
  assert(self._retainedBytes >= 0, "catalog byte ledger must never go negative")
  self._evictions = self._evictions + 1
end

-- Builds a worker-private catalog over one backend's native read delegate.
-- `readPhysical` keeps the original `(fullPath) -> data, sizeOrError` shape;
-- `versionId` scopes the retained keys to one worker version; `byteLimit` is
-- the fixed resident-byte ceiling and is never exceeded by retained entries.
---@param readPhysical fun(fullPath: string): string?, number|string?
---@param versionId string
---@param byteLimit integer
---@return CompressedAssetCatalog
function CompressedAssetCatalog.new(readPhysical, versionId, byteLimit)
  assert(type(readPhysical) == "function", "compressed catalog requires a native read delegate")
  assert(type(versionId) == "string" and versionId ~= "", "compressed catalog requires a version identity")
  assert(type(byteLimit) == "number" and byteLimit >= 0, "compressed catalog requires a non-negative byte limit")
  return setmetatable({
    _read = readPhysical,
    _prefix = versionId .. "/",
    _limit = math.floor(byteLimit),
    _entries = {},
    _oldest = nil,
    _newest = nil,
    _retainedBytes = 0,
    _reads = 0,
    _hits = 0,
    _evictions = 0,
  }, CompressedAssetCatalog)
end

-- Returns the backend's physical bytes for `fullPath`, retaining eligible
-- generated bytes for later reads. Hits return the stored string without a
-- native call; misses delegate exactly once, and a successful eligible
-- string is retained only when it fits the remaining or reclaimed budget.
-- Missing and failed reads are never retained, so a later publication is
-- visible on the next read.
---@param fullPath string save-directory-absolute physical path
---@return string? data physical bytes, or nil on miss/failure
---@return number|string? sizeOrError native size on hit, backend pair otherwise
function CompressedAssetCatalog:read(fullPath)
  local entry = type(fullPath) == "string" and self._entries[fullPath] or nil
  if entry ~= nil then
    self._hits = self._hits + 1
    self:_touch(fullPath)
    return entry.data, #entry.data
  end
  local data, sizeOrError = self._read(fullPath)
  self._reads = self._reads + 1
  if type(data) ~= "string" then
    return data, sizeOrError
  end
  if not self:_eligible(fullPath) then
    return data, sizeOrError
  end
  local size = #data
  if size > self._limit then
    return data, sizeOrError
  end
  while self._retainedBytes + size > self._limit do
    self:_evictOldest()
  end
  local fresh = { data = data, size = size, older = self._newest, newer = nil }
  self._entries[fullPath] = fresh
  if self._newest ~= nil then
    local newestEntry = assert(self._entries[self._newest], "catalog order links must resolve")
    newestEntry.newer = fullPath
  end
  self._newest = fullPath
  if self._oldest == nil then
    self._oldest = fullPath
  end
  self._retainedBytes = self._retainedBytes + size
  return data, sizeOrError
end

-- Scalar ledger snapshot: current retained bytes and entry count plus the
-- lifetime native-read, hit, and eviction counters.
---@return { retainedBytes: integer, entries: integer, reads: integer, hits: integer, evictions: integer }
function CompressedAssetCatalog:stats()
  local entries = 0
  for _ in pairs(self._entries) do
    entries = entries + 1
  end
  return {
    retainedBytes = self._retainedBytes,
    entries = entries,
    reads = self._reads,
    hits = self._hits,
    evictions = self._evictions,
  }
end

return CompressedAssetCatalog
